const r = await tools.pwsh({
  description: "Count douban posts and replies",
  command: `cd "D:\\GitHub\\My-second-brain\\50-知识\\AI工具\\_scripts"
node _b_db_parse.mjs _b_db_701765.html > _b_db_list.json 2>$null
$j = Get-Content _b_db_list.json -Raw -Encoding UTF8 | ConvertFrom-Json
Write-Host "posts=$($j.Count)"
$nums = $j | Where-Object { $_.replies -ne '' } | %{ [int]$_.replies }
Write-Host "withReplies=$($nums.Count) avgReplies=$([math]::Round(($nums | Measure-Object -Average).Average,1)) maxReplies=$(($nums|Measure-Object -Maximum).Maximum)"
Write-Host "--- top5 by replies ---"
$j | Sort-Object { if($_.replies -eq ''){0}else{[int]$_.replies} } -Descending | Select-Object -First 5 | %{ "$($_.replies) | $($_.title) | $($_.author)" }`,
  timeoutMs: 40000
});
console.log(r.kind === "foreground" ? r.stdout.text : JSON.stringify(r));
